// The only thing this workflow decides: whether the trigger landed.
// No business logic lives in n8n (ADR-030 §5) — the answer is produced by the
// turn the POST above started, and is read in SUNIL, not here.
const r = $input.first().json;
const status = r.statusCode ?? 0;
const body = r.body ?? {};
return [{ json: {
  workflow: 'sunil-morning-brief',
  delivered: status === 200,
  status,
  request_id: body.request_id ?? null,
  conversation_id: body.conversation_id ?? null,
  outcome: body.outcome ?? 'unreachable',
} }];
